# Independent base-R poststratification, observed-score audit and mask enumeration.
a<-commandArgs(TRUE);root<-a[1];outfile<-a[2];rd<-function(p)read.csv(file.path(root,p),colClasses='character',na.strings=NULL,check.names=FALSE)
s<-rd('model-specs/unit08_r.csv');stopifnot(!anyDuplicated(s$name));s<-setNames(s$value,s$name)
expected<-c(case_id='B8-U08-POSTSTRATIFIED-WEIGHTING',n='1600',groups='00|01|10|11',reverse_item='st4',base_weight='1',trim_cap='1.5',alpha='0.05',toy_n='8',toy_keep='3|2',toy_masks='24',target='B8-T01');stopifnot(setequal(names(s),names(expected)),all(s[names(expected)]==expected))
frame<-rd('data/anchor_participants.csv');base<-rd('data/anchor_baseline.csv');frame<-frame[order(frame$student_id),];stopifnot(nrow(frame)==1600,!anyDuplicated(frame$student_id),!anyDuplicated(base$student_id),setequal(base$student_id,frame$student_id[frame$responded_baseline=='1']))
stopifnot(all(frame$part_time%in%c('0','1')),all(frame$first_gen%in%c('0','1')),all(frame$responded_baseline%in%c('0','1')))
join<-match(frame$student_id,base$student_id);returned<-!is.na(join);stopifnot(all(frame$college_id[returned]==base$college_id[join[returned]]))
items<-paste0('st',1:5);raw<-matrix('',1600,5);raw[returned,]<-as.matrix(base[join[returned],items]);stopifnot(all(raw%in%c('','1','2','3','4','5')))
keyed<-matrix(NA_real_,1600,5);present<-raw!='';keyed[present]<-as.numeric(raw[present]);keyed[,4]<-6-keyed[,4];complete<-rowSums(is.na(keyed))==0;score<-rowMeans(keyed);group<-paste0(frame$part_time,frame$first_gen);groups<-c('00','01','10','11')
estimate<-function(Ns,ys,cap=1.5){stopifnot(length(Ns)>0,setequal(names(Ns),names(ys)),length(cap)==1,is.finite(cap),cap>0);N<-sum(Ns);n<-sum(lengths(ys));stats<-list();w<-y<-tw<-rw<-numeric();point<-variance<-bound<-0
 for(g in names(Ns)){Ng<-Ns[[g]];v<-ys[[g]];ng<-length(v);stopifnot(is.finite(Ng),Ng>=1,Ng==as.integer(Ng),ng>=1,ng<=Ng,ng>=2||ng==Ng,all(is.finite(v)),all(v>=1&v<=5));weight<-Ng/ng;share<-Ng/N;mean<-mean(v);fpc<-(Ng-ng)/Ng;vg<-if(ng==Ng)0 else share^2*fpc*var(v)/ng;bg<-if(ng==Ng)0 else share^2*fpc*4*Ng/(Ng-1)/ng;cw<-min(weight,cap);rcw<-cw*Ng/(ng*cw)
  point<-point+share*mean;variance<-variance+vg;bound<-bound+bg
  z<-list(n=Ng,complete=ng,complete_rate=ng/Ng,frame_share=share,complete_share=ng/n,mean=mean,analysis_weight=weight,calibrated_mass=ng*weight,trimmed_mass=ng*cw,trimmed_weight=cw,recalibrated_weight=rcw,variance_hat_contribution=vg,variance_bound_contribution=bg);if(ng>1)z$sample_variance<-var(v);stats[[g]]<-z;y<-c(y,v);w<-c(w,rep(weight,ng));tw<-c(tw,rep(cw,ng));rw<-c(rw,rep(rcw,ng))}
 norm<-w*n/N;radius<-sqrt(bound/.05);out<-list('roster/n'=N,'observed/complete'=n,'observed/complete_mean'=mean(y),'estimate/poststratified_mean'=point,'estimate/weighted_sum_per_N'=sum(w*y)/N,'weights/sum'=sum(w),'weights/min'=min(w),'weights/max'=max(w),'weights/ESS'=sum(w)^2/sum(w^2),'normalized/sum'=sum(norm),'normalized/mean_weight'=mean(norm),'normalized/ratio_mean'=sum(norm*y)/sum(norm),'normalized/ESS'=sum(norm)^2/sum(norm^2),'design/variance_hat'=variance,'design/estimated_SE'=sqrt(variance),'design/variance_bound'=bound,'confidence/radius'=radius,'confidence/lower'=max(1,point-radius),'confidence/upper'=min(5,point+radius),'trim/cap'=cap,'trim/sum'=sum(tw),'trim/lost_mass'=N-sum(tw),'trim/ratio_mean'=sum(tw*y)/sum(tw),'trim/ESS'=sum(tw)^2/sum(tw^2),'trim/max_weight'=max(tw),'recalibrated/ratio_mean'=sum(rw*y)/sum(rw),'recalibrated/max_weight'=max(rw))
 for(g in names(stats))for(k in names(stats[[g]]))out[[paste0('group/',g,'/',k)]]<-stats[[g]][[k]]
 list(out=out,stats=stats)}
Ns<-setNames(vapply(groups,function(g)sum(group==g),numeric(1)),groups);Rs<-setNames(vapply(groups,function(g)sum(group==g&returned),numeric(1)),groups);ys<-setNames(lapply(groups,function(g)score[group==g&complete]),groups);fit<-estimate(Ns,ys);out<-fit$out;stats<-fit$stats
put<-function(k,v){stopifnot(length(v)==1,is.finite(v));out[[k]]<<-as.numeric(v)};badmass<-badtotal<-0
for(g in groups){Ng<-Ns[[g]];rg<-Rs[[g]];ng<-length(ys[[g]]);stopifnot(ng>0,ng<=rg,rg<=Ng);extra<-list(returned=rg,return_rate=rg/Ng,completion_given_return=ng/rg,return_weight=Ng/rg,completion_factor=rg/ng,return_only_complete_mass=ng*Ng/rg,trimmed_composition=stats[[g]]$trimmed_mass/out[['trim/sum']]);for(k in names(extra))put(paste0('group/',g,'/',k),extra[[k]]);badmass<-badmass+ng*Ng/rg;badtotal<-badtotal+sum(ys[[g]])*Ng/rg}
rows<-data.frame(student_id=frame$student_id,group=group,responded=frame$responded_baseline,complete=as.character(as.integer(complete)),pattern=apply(present,1,function(v)paste0(as.integer(v),collapse='')),base_weight='1',stringsAsFactors=FALSE)
for(j in 1:5)rows[[paste0('raw_',items[j])]]<-raw[,j]
for(j in 1:5)rows[[paste0('keyed_',items[j])]]<-ifelse(is.na(keyed[,j]),'',sprintf('%.17g',keyed[,j]))
for(k in c('observed_score','return_weight','completion_factor','analysis_weight','normalized_weight','trimmed_weight','recalibrated_weight','contribution_to_mean'))rows[[k]]<-''
for(i in 1:1600){g<-group[i];w<-stats[[g]]$analysis_weight;if(returned[i])rows$return_weight[i]<-sprintf('%.17g',Ns[[g]]/Rs[[g]]);if(complete[i]){rows$observed_score[i]<-sprintf('%.17g',score[i]);rows$completion_factor[i]<-sprintf('%.17g',Rs[[g]]/length(ys[[g]]));rows$analysis_weight[i]<-sprintf('%.17g',w);rows$normalized_weight[i]<-sprintf('%.17g',w*sum(complete)/1600);rows$trimmed_weight[i]<-sprintf('%.17g',min(w,1.5));rows$recalibrated_weight[i]<-sprintf('%.17g',w);rows$contribution_to_mean[i]<-sprintf('%.17g',w*score[i]/1600)}}
S<-sum(keyed,na.rm=TRUE);missing<-sum(is.na(keyed));put('observed/returned',sum(returned));put('observed/keyed_sum',S);put('observed/missing_cells',missing);put('logical/item_lower',(S+missing)/8000);put('logical/item_upper',(S+5*missing)/8000);put('diagnostic/return_only_mass',badmass);put('diagnostic/return_only_ratio',badtotal/badmass)
toy<-rd('model-specs/unit08_population.csv');stopifnot(identical(toy$id,paste0('W',1:8)),identical(toy$group,as.character(rep(0:1,each=4))),identical(toy$y,as.character(c(1,1,3,3,3,3,5,5))))
full<-list('0'=as.numeric(toy$y[1:4]),'1'=as.numeric(toy$y[5:8]));tn<-c('0'=4,'1'=4);truth<-mean(as.numeric(toy$y));comb0<-combn(1:4,3);comb1<-combn(5:8,2);results<-list()
for(i in 1:ncol(comb0))for(j in 1:ncol(comb1)){ix<-c(comb0[,i],comb1[,j]);tag<-paste0(as.integer(1:8%in%ix),collapse='');ss<-list('0'=as.numeric(toy$y[comb0[,i]]),'1'=as.numeric(toy$y[comb1[,j]]));f<-estimate(tn,ss)$out;z<-c(estimate=f[['estimate/poststratified_mean']],unweighted=f[['observed/complete_mean']],trimmed=f[['trim/ratio_mean']],variance_hat=f[['design/variance_hat']],covered=as.integer(f[['confidence/lower']]<=truth&&truth<=f[['confidence/upper']]));results[[length(results)+1]]<-z;for(k in names(z))put(paste0('toy/mask/',tag,'/',k),z[k])}
put('toy/true_mean',truth);put('toy/masks',length(results));mat<-do.call(rbind,results)
for(k in colnames(mat)){v<-mat[,k];put(paste0('toy/expectation/',k),mean(v));if(k%in%c('estimate','unweighted','trimmed')){put(paste0('toy/mask_variance/',k),mean((v-mean(v))^2));put(paste0('toy/MSE/',k),mean((v-truth)^2))}}
put('toy/design_true_variance',.25*((1-3/4)*var(full[['0']])/3+(1-2/4)*var(full[['1']])/2))
allknown<-estimate(tn,full)$out;for(k in c('estimate/poststratified_mean','design/variance_hat','design/variance_bound','confidence/lower','confidence/upper'))put(paste0('toy/all_known/',k),allknown[[k]])
selected<-list('0'=sort(full[['0']])[1:3],'1'=sort(full[['1']])[1:2]);fail<-estimate(tn,selected);put('toy/selection_failure/estimate',fail$out[['estimate/poststratified_mean']]);put('toy/selection_failure/calibration_error',max(vapply(names(tn),function(g)abs(fail$stats[[g]]$calibrated_mass-tn[[g]]),numeric(1))))
refused<-tryCatch({estimate(tn,list('0'=full[['0']][1:3],'1'=numeric()));FALSE},error=function(e)TRUE);stopifnot(refused);put('toy/positivity_failure/refused',1)
keys<-sort(names(out));stopifnot(all(is.finite(unlist(out))));write.table(data.frame(key=keys,value=vapply(out[keys],function(v)sprintf('%.17g',v),character(1))),outfile,sep=',',row.names=FALSE,col.names=TRUE,quote=FALSE);write.table(rows,sub('\\.csv$','_people.csv',outfile),sep=',',row.names=FALSE,col.names=TRUE,quote=FALSE,na='');cat('UNIT08_BASE_R_OK target=B8-T01 response_design_assumed=true\n')
